-- JAMB TRADE initial schema. Run once in Supabase SQL Editor.
create extension if not exists pgcrypto;
create table public.businesses(id uuid primary key default gen_random_uuid(),name text not null check(length(name) between 3 and 160),type text not null check(type in ('retailer','wholesaler')),verified boolean not null default false,created_at timestamptz not null default now());
create table public.business_members(business_id uuid not null references public.businesses(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in ('retailer','wholesaler','manager')),primary key(business_id,user_id));
create table public.products(id uuid primary key default gen_random_uuid(),supplier_id uuid not null references public.businesses(id),name text not null,category text not null default 'General',unit text not null default 'carton',sku text,price numeric(18,2) not null check(price>0),available_qty integer not null default 0 check(available_qty>=0),active boolean not null default true,created_at timestamptz not null default now());
create table public.orders(id uuid primary key default gen_random_uuid(),retailer_id uuid not null references public.businesses(id),supplier_id uuid not null references public.businesses(id),status text not null default 'pending_confirmation' check(status in ('pending_confirmation','confirmed','cancelled','rejected','preparing','assigned','in_transit','delivered')),subtotal numeric(18,2) not null check(subtotal>=0),delivery_fee numeric(18,2) not null default 0 check(delivery_fee>=0),total numeric(18,2) generated always as (subtotal+delivery_fee) stored,notes text,created_at timestamptz not null default now());
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid not null references public.products(id),quantity integer not null check(quantity>0),unit_price numeric(18,2) not null check(unit_price>0),line_total numeric(18,2) generated always as (quantity*unit_price) stored,unique(order_id,product_id));
create index on public.products(supplier_id);create index on public.orders(retailer_id,created_at desc);create index on public.orders(supplier_id,created_at desc);
create function public.is_business_member(p_id uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.business_members where business_id=p_id and user_id=(select auth.uid()))$$;
create function public.is_business_role(p_id uuid,p_role text) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.business_members where business_id=p_id and user_id=(select auth.uid()) and role=p_role)$$;
create view public.catalog_products with (security_invoker=true) as select p.id,p.supplier_id,p.name,p.category,p.unit,p.price,p.available_qty,b.name as supplier_name from public.products p join public.businesses b on b.id=p.supplier_id where p.active and b.verified and b.type='wholesaler';
create view public.my_businesses with (security_invoker=true) as select b.id,b.name,b.type,b.verified,m.role as member_role from public.businesses b join public.business_members m on m.business_id=b.id where m.user_id=(select auth.uid());
alter table public.businesses enable row level security;alter table public.business_members enable row level security;alter table public.products enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;
create policy businesses_select on public.businesses for select to authenticated using(verified or public.is_business_member(id));
create policy members_select on public.business_members for select to authenticated using(user_id=(select auth.uid()));
create policy products_select on public.products for select to authenticated using((active and exists(select 1 from public.businesses b where b.id=supplier_id and b.verified and b.type='wholesaler')) or public.is_business_member(supplier_id));
create policy orders_select on public.orders for select to authenticated using(public.is_business_member(retailer_id) or public.is_business_member(supplier_id));
create policy items_select on public.order_items for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and (public.is_business_member(o.retailer_id) or public.is_business_member(o.supplier_id))));
-- Allow anonymous browsing of verified supplier catalogue.
create policy public_businesses on public.businesses for select to anon using(verified and type='wholesaler');
create policy public_products on public.products for select to anon using(active and exists(select 1 from public.businesses b where b.id=supplier_id and b.verified and b.type='wholesaler'));
grant select on public.businesses,public.products,public.catalog_products to anon,authenticated;
grant select on public.business_members,public.orders,public.order_items,public.my_businesses to authenticated;
create function public.register_business(p_name text,p_type text) returns uuid language plpgsql security definer set search_path='' as $$declare v_id uuid;begin if auth.uid() is null then raise exception 'Authentication required';end if;if p_type not in ('retailer','wholesaler') or length(trim(p_name)) not between 3 and 160 then raise exception 'Invalid business';end if;insert into public.businesses(name,type) values(trim(p_name),p_type) returning id into v_id;insert into public.business_members(business_id,user_id,role) values(v_id,auth.uid(),p_type);return v_id;end$$;
create function public.place_order(p_business_id uuid,p_items jsonb,p_notes text default '') returns uuid language plpgsql security definer set search_path='' as $$declare v_supplier uuid;v_order uuid;v_total numeric(18,2):=0;v_count integer;v_input_count integer;v_record record;begin if not public.is_business_role(p_business_id,'retailer') then raise exception 'Retailer access required';end if;if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)<1 or jsonb_array_length(p_items)>50 then raise exception 'Invalid cart';end if;if length(coalesce(p_notes,''))>500 then raise exception 'Notes too long';end if;select count(*),count(distinct product_id) into v_input_count,v_count from jsonb_to_recordset(p_items) as x(product_id uuid,quantity integer);if v_input_count<>v_count then raise exception 'Duplicate product in cart';end if;for v_record in select p.id,p.supplier_id,p.price,p.available_qty,x.quantity,b.verified from jsonb_to_recordset(p_items) as x(product_id uuid,quantity integer) join public.products p on p.id=x.product_id join public.businesses b on b.id=p.supplier_id where p.active and b.type='wholesaler' order by p.id for update of p loop if v_record.quantity is null or v_record.quantity<1 or v_record.quantity>10000 then raise exception 'Invalid quantity';end if;if not v_record.verified then raise exception 'Unverified supplier';end if;if v_record.available_qty<v_record.quantity then raise exception 'Insufficient stock';end if;if v_supplier is null then v_supplier:=v_record.supplier_id;elsif v_supplier<>v_record.supplier_id then raise exception 'One supplier per order';end if;v_total:=v_total+v_record.price*v_record.quantity;v_count:=v_count-1;end loop;if v_count<>0 or v_supplier is null then raise exception 'One or more products are unavailable';end if;insert into public.orders(retailer_id,supplier_id,subtotal,notes) values(p_business_id,v_supplier,v_total,p_notes) returning id into v_order;insert into public.order_items(order_id,product_id,quantity,unit_price) select v_order,p.id,x.quantity,p.price from jsonb_to_recordset(p_items) as x(product_id uuid,quantity integer) join public.products p on p.id=x.product_id;return v_order;end$$;
create function public.confirm_supplier_order(p_order_id uuid) returns void language plpgsql security definer set search_path='' as $$declare v_order public.orders%rowtype;v_item record;begin select * into v_order from public.orders where id=p_order_id for update;if not found or not public.is_business_role(v_order.supplier_id,'wholesaler') then raise exception 'Supplier access required';end if;if v_order.status<>'pending_confirmation' then raise exception 'Order cannot be confirmed';end if;for v_item in select product_id,quantity from public.order_items where order_id=p_order_id order by product_id loop update public.products set available_qty=available_qty-v_item.quantity where id=v_item.product_id and supplier_id=v_order.supplier_id and available_qty>=v_item.quantity;if not found then raise exception 'Insufficient stock for confirmation';end if;end loop;update public.orders set status='confirmed' where id=p_order_id;end$$;
revoke all on function public.register_business(text,text) from public;revoke all on function public.place_order(uuid,jsonb,text) from public;revoke all on function public.confirm_supplier_order(uuid) from public;
grant execute on function public.register_business(text,text),public.place_order(uuid,jsonb,text),public.confirm_supplier_order(uuid) to authenticated;
-- NOTE: No direct write policies exist. Use trusted server-side admin functions for inventory changes and verification.
